    match j with
    | JStr "Stack" -> Ok LayoutKind.Stack
    | JStr "Row" -> Ok LayoutKind.Row
    | JStr "Grid" -> Ok LayoutKind.Grid
    | JStr __s -> dFail DecodeCode.UnknownTag "one of 'Stack', 'Row', 'Grid'" ("case '" + __s + "' of enum 'LayoutKind'")
    | __j -> Error(Decoder.wrongKind "string" __j)

let private decLevel (j: JVal) : Result<Level, DecodeError> =
    match j with
    | JStr "low" -> Ok Level.Low
    | JStr "medium" -> Ok Level.Medium
    | JStr "high" -> Ok Level.High
    | JStr __s -> dFail DecodeCode.UnknownTag "one of 'low', 'medium', 'high'" ("case '" + __s + "' of enum 'Level'")
    | __j -> Error(Decoder.wrongKind "string" __j)

let private decStrictness (j: JVal) : Result<Strictness, DecodeError> =
    match j with
    | JStr "StrictReplay" -> Ok Strictness.StrictReplay
    | JStr "AdvisoryWarning" -> Ok Strictness.AdvisoryWarning
    | JStr __s -> dFail DecodeCode.UnknownTag "one of 'StrictReplay', 'AdvisoryWarning'" ("case '" + __s + "' of enum 'Strictness'")
    | __j -> Error(Decoder.wrongKind "string" __j)

let rec private decNodeKind (j: JVal) : Result<NodeKind, DecodeError> =
    dObj j |> Result.bind (fun __fs ->
    dTag __fs |> Result.bind (fun __t ->
    match __t with
    | "Bind" -> decBindSpec j |> Result.map NodeKind.Bind
    | "Embed" -> decEmbedSpec j |> Result.map NodeKind.Embed
    | "Group" -> decGroupSpec j |> Result.map NodeKind.Group
    | "Link" -> decLinkSpec j |> Result.map NodeKind.Link
    | "Measure" -> decMeasureSpec j |> Result.map NodeKind.Measure
    | "Note" -> decNoteSpec j |> Result.map NodeKind.Note
    | "Tally" -> decTallySpec j |> Result.map NodeKind.Tally
    | __other -> dUnknown "one of 'Bind', 'Embed', 'Group', 'Link', 'Measure', 'Note', 'Tally'" ("$type '" + __other + "'")))

and private decNode (j: JVal) : Result<Node, DecodeError> =
    dObj j |> Result.bind (fun __fs ->
    dReq "id" __fs dStr |> Result.bind (fun id ->
    dReq "kind" __fs decNodeKind |> Result.bind (fun kind ->
    dOpt "hidden" __fs dBool |> Result.bind (fun hidden ->
    dOpt "label" __fs dStr |> Result.bind (fun label ->
    Ok { Id = id; Kind = kind; Hidden = hidden; Label = label })))))

and private decBinding<'T> (decT: JVal -> Result<'T, DecodeError>) (j: JVal) : Result<Binding<'T>, DecodeError> =
    match j with
    | JObj __fs ->
        dTag __fs |> Result.bind (fun __t ->
        match __t with
        | "Local" ->
            dReq "parse" __fs (fun (__j: JVal) -> dSentinel "<closure>" __j |> Result.map (fun () -> (fun (v: JVal) -> decT v |> Result.toOption))) |> Result.bind (fun parse ->
            dReq "value" __fs decT |> Result.bind (fun value ->
            Ok(Binding.Local(parse, value))))
        | "Ref" ->
            dReq "name" __fs dStr |> Result.bind (fun name ->
            Ok(Binding.Ref(name)))
        | __other -> dUnknown "one of 'Local', 'Ref'" ("$type '" + __other + "'"))
    | __j -> Error(Decoder.wrongKind "object" __j)

and private decSlot<'T> (decT: JVal -> Result<'T, DecodeError>) (j: JVal) : Result<Slot<'T>, DecodeError> =
    match j with
    | JObj __fs ->
        dTag __fs |> Result.bind (fun __t ->
        match __t with
        | "Fixed" ->
            dReq "value" __fs decT |> Result.bind (fun value ->
            Ok(Slot.Fixed(value)))
        | "Ref" ->
            dReq "name" __fs dStr |> Result.bind (fun name ->
            Ok(Slot.Ref(name)))
        | __other -> dUnknown "one of 'Fixed', 'Ref'" ("$type '" + __other + "'"))
    | __j -> Error(Decoder.wrongKind "object" __j)

and private decText (j: JVal) : Result<Text, DecodeError> =
    match j with
    | JObj __fs ->
        dTag __fs |> Result.bind (fun __t ->
        match __t with
        | "Inline" ->
            dReq "text" __fs dStr |> Result.bind (fun text ->
            Ok(Text.Inline(text)))
        | "Lookup" ->
            dOpt "args" __fs (dMap dStr) |> Result.bind (fun args ->
            dReq "key" __fs dStr |> dRefine (fun key ->
            Ok(Text.Lookup(args, key))))
        | __other -> dUnknown "one of 'Inline', 'Lookup'" ("$type '" + __other + "'"))
    | __bare ->
        dStr __bare |> Result.bind (fun text -> Ok(Text.Inline(text)))

and private decContentHash (j: JVal) : Result<ContentHash, DecodeError> =
    dObj j |> Result.bind (fun __fs ->
    dReq "hash" __fs dStr |> Result.bind (fun hash ->
    dReq "strictness" __fs decStrictness |> Result.bind (fun strictness ->
    Ok { Hash = hash; Strictness = strictness })))

and private decPoint (j: JVal) : Result<Point, DecodeError> =
    dObj j |> Result.bind (fun __fs ->
    dReq "x" __fs dFloat |> Result.bind (fun x ->
    dReq "y" __fs dFloat |> Result.bind (fun y ->
    Ok { X = x; Y = y })))

and private decBindSpec (j: JVal) : Result<BindSpec, DecodeError> =
    dObj j |> Result.bind (fun __fs ->
    dReq "binding" __fs (decBinding dInt) |> Result.bind (fun binding ->
    Ok { Binding = binding }))

and private decEmbedSpec (j: JVal) : Result<EmbedSpec, DecodeError> =
    dObj j |> Result.bind (fun __fs ->
    dReq "componentId" __fs dStr |> Result.bind (fun componentId ->
    dOpt "contentHash" __fs decContentHash |> Result.bind (fun contentHash ->
    dReq "moduleId" __fs dStr |> Result.bind (fun moduleId ->
    Ok (ignore) |> Result.bind (fun onMount ->
    dOpt "props" __fs (dMap dJson) |> Result.bind (fun props ->
    Ok { ComponentId = componentId; ContentHash = contentHash; ModuleId = moduleId; OnMount = onMount; Props = props }))))))

and private decGroupSpec (j: JVal) : Result<GroupSpec, DecodeError> =
    dObj j |> Result.bind (fun __fs ->
    dReq "children" __fs (dList decNode) |> Result.bind (fun children ->
    dDef "layout" __fs decLayoutKind (LayoutKind.Stack) |> Result.bind (fun layout ->
    dReq "onSelect" __fs (fun (__j: JVal) -> dSentinel "<closure>" __j |> Result.map (fun () -> ignore)) |> Result.bind (fun onSelect ->
    Ok { Children = children; Layout = layout; OnSelect = onSelect }))))

and private decLinkSpec (j: JVal) : Result<LinkSpec, DecodeError> =
    dObj j |> Result.bind (fun __fs ->
    dReq "href" __fs (decSlot dStr) |> Result.bind (fun href ->
    dReq "label" __fs decText |> Result.bind (fun label ->
    dReq "onClick" __fs (dSentinel "<closure>") |> Result.bind (fun onClick ->
    Ok { Href = href; Label = label; OnClick = onClick }))))

and private decMeasureSpec (j: JVal) : Result<MeasureSpec, DecodeError> =
    dObj j |> Result.bind (fun __fs ->
    dReq "label" __fs decText |> Result.bind (fun label ->
    dDef "level" __fs decLevel (Level.Low) |> Result.bind (fun level ->
    dOpt "origin" __fs decPoint |> Result.bind (fun origin ->
    dReq "raw" __fs (dSentinel "<opaque>") |> Result.bind (fun raw ->
    dReq "series" __fs (fun (__j: JVal) -> dHosted ((decSeries) __j)) |> Result.bind (fun series ->
    dDef "value" __fs (decSlot dFloat) (Slot.Fixed(0.0)) |> Result.bind (fun value ->
    Ok { Label = label; Level = level; Origin = origin; Raw = raw; Series = series; Value = value })))))))

and private decNoteSpec (j: JVal) : Result<NoteSpec, DecodeError> =
        dObj j |> Result.bind (fun fs -> dReq "body" fs decText) |> Result.map (fun t -> { Body = t })

and private decTallySpec (j: JVal) : Result<TallySpec, DecodeError> =
    dObj j |> Result.bind (fun __fs ->
    dReq "amount" __fs (dText "decimal" isDecimalText) |> Result.bind (fun amount ->
    dOpt "at" __fs (dText "timeOfDay" isTimeOfDayText) |> Result.bind (fun at ->
    dReq "count" __fs dInt64 |> Result.bind (fun count ->
    dOpt "digest" __fs dBytes |> Result.bind (fun digest ->
    dReq "grid" __fs (dKeyedMap (fun (__t0, __t1) -> JArr [ JInt __t0; JBool __t1 ]) (fun (__j: JVal) -> match __j with | JArr [ __x0; __x1 ] -> dInt __x0 |> dUnder (PathSegment.Index 0) |> Result.bind (fun __v0 -> dBool __x1 |> dUnder (PathSegment.Index 1) |> Result.bind (fun __v1 -> Ok(__v0, __v1))) | JArr __xs -> dFail DecodeCode.OutOfRange "an array of 2 items" (sprintf "an array of %d items" (List.length __xs)) | __other -> Error(Decoder.wrongKind "array" __other)) dStr) |> Result.bind (fun grid ->
    dReq "levels" __fs (dKeyedMap encLevel decLevel (dText "duration" isDurationText)) |> Result.bind (fun levels ->
    dReq "pair" __fs (fun (__j: JVal) -> match __j with | JArr [ __x0; __x1 ] -> dInt64 __x0 |> dUnder (PathSegment.Index 0) |> Result.bind (fun __v0 -> (fun (__j: JVal) -> match __j with | JArr [ __x0; __x1 ] -> dStr __x0 |> dUnder (PathSegment.Index 0) |> Result.bind (fun __v0 -> dFloat __x1 |> dUnder (PathSegment.Index 1) |> Result.bind (fun __v1 -> Ok(__v0, __v1))) | JArr __xs -> dFail DecodeCode.OutOfRange "an array of 2 items" (sprintf "an array of %d items" (List.length __xs)) | __other -> Error(Decoder.wrongKind "array" __other)) __x1 |> dUnder (PathSegment.Index 1) |> Result.bind (fun __v1 -> Ok(__v0, __v1))) | JArr __xs -> dFail DecodeCode.OutOfRange "an array of 2 items" (sprintf "an array of %d items" (List.length __xs)) | __other -> Error(Decoder.wrongKind "array" __other)) |> Result.bind (fun pair ->
    dReq "span" __fs (dText "duration" isDurationText) |> Result.bind (fun span ->
    dReq "tags" __fs (dSet JStr dStr) |> Result.bind (fun tags ->
    Ok { Amount = amount; At = at; Count = count; Digest = digest; Grid = grid; Levels = levels; Pair = pair; Span = span; Tags = tags }))))))))))

and private decReferenceMarker (j: JVal) : Result<ReferenceMarker, string> =
        jprop "note" j |> Result.bind jstr |> Result.map (fun n -> { Note = n })

/// Structural decode. The policy layer (diagnostics, §16 lenient-accept,
/// the reject set) composes ABOVE this — see the Phase 672 note in the generator.
/// A refusal is Core's `DecodeError` (Phase 337): the code and path the IDL interpreter
/// reports for the same document, and this layer's sentence (`DecodeError.describe`).
let decodeNode (s: string) : Result<Node, DecodeError> =
    Decoder.parse ReadOptions.strict s |> Result.bind decNode

let private witnessKindTag (n: Node) : string =
    match n.Kind with
    | NodeKind.Bind _ -> "Bind"
    | NodeKind.Embed _ -> "Embed"
    | NodeKind.Group _ -> "Group"
    | NodeKind.Link _ -> "Link"
    | NodeKind.Measure _ -> "Measure"
    | NodeKind.Note _ -> "Note"
    | NodeKind.Tally _ -> "Tally"

let private witnessChildren (n: Node) : Node list =
    match n.Kind with
    | NodeKind.Group s -> s.Children
    | _ -> []

let private witnessReplaceChildren (n: Node) (kids: Node list) : Node =
    match n.Kind with
    | NodeKind.Group s -> { n with Kind = NodeKind.Group { s with Children = kids } }
    | _ -> n

let nodeWitness: NodeWitness<Node, string> =
    { Id = fun n -> n.Id
      KindTag = witnessKindTag
      Children = witnessChildren
      ReplaceChildren = witnessReplaceChildren }

// Validator scaffold — register domain RuleFamilies into `reg`; rule content stays domain-side.
let runValidator (reg: Validator.RuleRegistry<Node, string>) (root: Node) : Defect<string> list =
    Validator.runAll nodeWitness reg root

// Smart constructors — required-without-default fields are parameters; IDL-declared
// defaults are filled, other optionals default to None.

let mkBind (id: string) (binding: Binding<int>) : Node =
    { Id = id; Kind = NodeKind.Bind { Binding = binding }; Hidden = None; Label = None }

let mkEmbed (id: string) (componentId: string) (moduleId: string) : Node =
    { Id = id; Kind = NodeKind.Embed { ComponentId = componentId; ContentHash = None; ModuleId = moduleId; OnMount = ignore; Props = None }; Hidden = None; Label = None }

let mkGroup (id: string) (children: Node list) (onSelect: (int -> unit)) : Node =
    { Id = id; Kind = NodeKind.Group { Children = children; Layout = LayoutKind.Stack; OnSelect = onSelect }; Hidden = None; Label = None }

let mkLink (id: string) (href: Slot<string>) (label: Text) (onClick: unit) : Node =
    { Id = id; Kind = NodeKind.Link { Href = href; Label = label; OnClick = onClick }; Hidden = None; Label = None }

let mkMeasure (id: string) (label: Text) (raw: unit) (series: float list) : Node =
    { Id = id; Kind = NodeKind.Measure { Label = label; Level = Level.Low; Origin = None; Raw = raw; Series = series; Value = Slot.Fixed(0.0) }; Hidden = None; Label = None }

let mkNote (body: Text) : NoteSpec = { Body = body }

let mkTally (id: string) (amount: string) (count: int64) (grid: Map<(int * bool), string>) (levels: Map<Level, string>) (pair: (int64 * (string * float))) (span: string) (tags: Set<string>) : Node =
    { Id = id; Kind = NodeKind.Tally { Amount = amount; At = None; Count = count; Digest = None; Grid = grid; Levels = levels; Pair = pair; Span = span; Tags = tags }; Hidden = None; Label = None }

/// Phase 541 — the collecting decoders a host may override, one per type the vocabulary reaches
/// through a nested position. Each takes the record it is read from, so a decoder that delegates
/// to `collectingDecoders.<Type> self` keeps every position beneath it reading `self`.
/// Phase 562 — every enumeration and JSON scalar has a field too; a generic union's field is its
/// `Collecting<Union>` seam, generic in the union's parameters; and `Absent` is asked at every
/// declared member an object does not carry, with the holder's name, the key and the object.
type CollectingDecoders =
    { Node: CollectingDecoders -> JVal -> Result<Node, DecodeError list>
      Text: CollectingDecoders -> JVal -> Result<Text, DecodeError list>
      ContentHash: CollectingDecoders -> JVal -> Result<ContentHash, DecodeError list>
      Point: CollectingDecoders -> JVal -> Result<Point, DecodeError list>
      BindSpec: CollectingDecoders -> JVal -> Result<BindSpec, DecodeError list>
      EmbedSpec: CollectingDecoders -> JVal -> Result<EmbedSpec, DecodeError list>
      GroupSpec: CollectingDecoders -> JVal -> Result<GroupSpec, DecodeError list>
      LinkSpec: CollectingDecoders -> JVal -> Result<LinkSpec, DecodeError list>
      MeasureSpec: CollectingDecoders -> JVal -> Result<MeasureSpec, DecodeError list>
      TallySpec: CollectingDecoders -> JVal -> Result<TallySpec, DecodeError list>
      LayoutKind: CollectingDecoders -> JVal -> Result<LayoutKind, DecodeError list>
      Level: CollectingDecoders -> JVal -> Result<Level, DecodeError list>
      Strictness: CollectingDecoders -> JVal -> Result<Strictness, DecodeError list>
      String: CollectingDecoders -> JVal -> Result<string, DecodeError list>
      Int: CollectingDecoders -> JVal -> Result<int, DecodeError list>
      Float: CollectingDecoders -> JVal -> Result<float, DecodeError list>
      Bool: CollectingDecoders -> JVal -> Result<bool, DecodeError list>
      Binding: CollectingBinding
      Slot: CollectingSlot
      Absent: CollectingDecoders -> string -> string -> JVal -> Result<JVal option, DecodeError list> }

/// Phase 562 — the collecting decoder of `Binding` at every instantiation, from its argument decoders.
and CollectingBinding =
    abstract Decode<'T> : CollectingDecoders * (JVal -> Result<'T, DecodeError list>) * Instantiation<'T> * JVal -> Result<Binding<'T>, DecodeError list>

/// Phase 562 — the collecting decoder of `Slot` at every instantiation, from its argument decoders.
and CollectingSlot =
    abstract Decode<'T> : CollectingDecoders * (JVal -> Result<'T, DecodeError list>) * Instantiation<'T> * JVal -> Result<Slot<'T>, DecodeError list>

/// Phase 635 — the witness of one instantiation of a generic union's parameter, passed beside its
/// decoder: a case per concrete type the vocabulary instantiates one at, carrying the identity both
/// ways between that type and `'T`, so a host builds a value that depends on the instantiation
/// without a runtime type test; `Open` for an argument no case names (one built over a type parameter).
and [<RequireQualifiedAccess>] Instantiation<'T> =
    | Float of into: (float -> 'T) * out: ('T -> float)
    | Int of into: (int -> 'T) * out: ('T -> int)
    | String of into: (string -> 'T) * out: ('T -> string)

// ---------------------------------------------------------------------------
// Phase 377 — COLLECTING DECODERS. Beside every short-circuiting `dec*` decoder above, a `col*`
// decoder answers EVERY defect it finds, as a `DecodeError list`, in one deterministic order:
//   - an object's members in FIELD DECLARATION ORDER (a node: `id`, its kind, then its envelope
//     fields), each member's defects at that member's position, its nested defects included
//     (depth-first);
//   - a list's items in index order, and a map's entries in document order;
//   - a leaf (a scalar, an enum, a sentinel, a hosted slot, verbatim JSON) reports at most one
//     defect, and so does a value of the wrong kind or an absent or unknown discriminator, whose
//     members are never read.
// The first defect of a collecting decoder is the defect its short-circuiting twin reports, and on
// a clean input both answer the same value. A case refine runs once its members all decoded, and a
// host projection supplies only a short-circuiting decoder, so each adds at most one defect of its
// own. Phase 541 — every node, non-generic union, record and kind spec is read through one record
// of decoders, `CollectingDecoders`, so a host's decoder at a type applies at every depth. Phase
// 562 — so is every enumeration, JSON scalar and generic union, and a declared member the object
// does not carry asks the record's `Absent` first. Codes and paths are Core's `DecodeError`; a
// consumer whose specification orders or names defects differently maps them at its own seam.
// ---------------------------------------------------------------------------
let private cOne (r: Result<'T, DecodeError>) : Result<'T, DecodeError list> =
    match r with
    | Ok v -> Ok v
    | Error e -> Error [ e ]

let private cLift (dec: JVal -> Result<'T, DecodeError>) (j: JVal) : Result<'T, DecodeError list> = cOne (dec j)

let private cErrs (r: Result<'T, DecodeError list>) : DecodeError list =
    match r with
    | Ok _ -> []
    | Error es -> es

// One step further from the root, for every defect a member or an item answered.
let private cUnder (step: PathSegment) (r: Result<'T, DecodeError list>) : Result<'T, DecodeError list> =
    match r with
    | Ok v -> Ok v
    | Error es -> Error(es |> List.map (DecodeError.under step))

// The first defect — how a short-circuiting decoder is handed a collecting codec.
let private cFirst (r: Result<'T, DecodeError list>) : Result<'T, DecodeError> =
    match r with
    | Ok v -> Ok v
    | Error(e :: _) -> Error e
    | Error [] -> dFail DecodeCode.SchemaFault "a refusal" "a collecting decoder answered no defect and no value"

let private cObj (j: JVal) : Result<(string * JVal) list, DecodeError list> = cOne (dObj j)

let private cList (dec: JVal -> Result<'T, DecodeError list>) (j: JVal) : Result<'T list, DecodeError list> =
    match j with
    | JArr xs ->
        let results = xs |> List.mapi (fun i x -> dec x |> cUnder (PathSegment.Index i))

        match results |> List.collect cErrs with
        | [] -> Ok(results |> List.choose (function Ok v -> Some v | Error _ -> None))
        | errors -> Error errors
    | other -> cOne (Error(Decoder.wrongKind "array" other))

// Every entry is checked, in document order; a repeated key keeps its FIRST value, as `dMap` does.
let private cMap (dec: JVal -> Result<'T, DecodeError list>) (j: JVal) : Result<Map<string, 'T>, DecodeError list> =
    match j with
    | JObj fs ->
        let results = fs |> List.map (fun (k, v) -> k, (dec v |> cUnder (PathSegment.Key k)))

        match results |> List.collect (snd >> cErrs) with
        | [] ->
            (Map.empty, results)
            ||> List.fold (fun items (k, r) ->
                match r with
                | Ok d when not (Map.containsKey k items) -> Map.add k d items
                | _ -> items)
            |> Ok
        | errors -> Error errors
    | other -> cOne (Error(Decoder.wrongKind "object" other))

// The node's own framing (its `kind` member) read under its key: absent is `dReq`'s refusal.
let private cReq (name: string) (fs: (string * JVal) list) (dec: JVal -> Result<'T, DecodeError list>) : Result<'T, DecodeError list> =
    match fs |> List.tryFind (fun (k, _) -> k = name) with
    | Some(_, v) -> dec v |> cUnder (PathSegment.Key name)
    | None -> cOne (dReq name fs (fun _ -> dFail DecodeCode.SchemaFault "never read" "never read"))

// Phase 562 — a DECLARED member the object `j` does not carry: the record's `Absent` is asked first,
// with the holder's name and the member's key. `Ok None` is the reading the member's presence rule
// gives absence (`none`); `Ok(Some v)` reads `v` as the member; a refusal is the member's own, at its
// key. The default `Absent` answers `Ok None`, so a record that overrides nothing reads as before.
let private cAbsent
    (ov: CollectingDecoders)
    (holder: string)
    (j: JVal)
    (name: string)
    (dec: JVal -> Result<'T, DecodeError list>)
    (none: unit -> Result<'T, DecodeError list>)
    : Result<'T, DecodeError list> =
    match ov.Absent ov holder name j with
    | Ok None -> none ()
    | Ok(Some v) -> dec v |> cUnder (PathSegment.Key name)
    | Error es -> Error(es |> List.map (DecodeError.under (PathSegment.Key name)))

// A required declared member: absent (and the hook answering `None`) is `dReq`'s refusal.
let private cReqAt (ov: CollectingDecoders) (holder: string) (j: JVal) (name: string) (fs: (string * JVal) list) (dec: JVal -> Result<'T, DecodeError list>) : Result<'T, DecodeError list> =
    match fs |> List.tryFind (fun (k, _) -> k = name) with
    | Some(_, v) -> dec v |> cUnder (PathSegment.Key name)
    | None -> cAbsent ov holder j name dec (fun () -> cOne (dReq name fs (fun _ -> dFail DecodeCode.SchemaFault "never read" "never read")))

let private cOptAt (ov: CollectingDecoders) (holder: string) (j: JVal) (name: string) (fs: (string * JVal) list) (dec: JVal -> Result<'T, DecodeError list>) : Result<'T option, DecodeError list> =
    match fs |> List.tryFind (fun (k, _) -> k = name) with
    | Some(_, v) -> dec v |> cUnder (PathSegment.Key name) |> Result.map Some
    | None -> cAbsent ov holder j name (dec >> Result.map Some) (fun () -> Ok None)

let private cDefAt (ov: CollectingDecoders) (holder: string) (j: JVal) (name: string) (fs: (string * JVal) list) (dec: JVal -> Result<'T, DecodeError list>) (dflt: 'T) : Result<'T, DecodeError list> =
    match fs |> List.tryFind (fun (k, _) -> k = name) with
    | Some(_, v) -> dec v |> cUnder (PathSegment.Key name)
    | None -> cAbsent ov holder j name dec (fun () -> Ok dflt)

// Phase 562 — the generated decoders at the JSON scalars, each the short-circuiting reader lifted.
let private colString (_: CollectingDecoders) (j: JVal) : Result<string, DecodeError list> = cOne (dStr j)

let private colInt (_: CollectingDecoders) (j: JVal) : Result<int, DecodeError list> = cOne (dInt j)

let private colFloat (_: CollectingDecoders) (j: JVal) : Result<float, DecodeError list> = cOne (dFloat j)

let private colBool (_: CollectingDecoders) (j: JVal) : Result<bool, DecodeError list> = cOne (dBool j)

// Phase 562 — the generated `Absent`: every absent member reads by its presence rule.
let private colAbsent (_: CollectingDecoders) (_: string) (_: string) (_: JVal) : Result<JVal option, DecodeError list> = Ok None

// A declared case refine over the COLLECTED members: every member decoded, and the refine's
// refusal is `dRefine`'s — `OutOfRange` at the case's object, its sentence unchanged.
let private cRefine (f: 'T -> Result<'U, string>) (r: Result<'T, DecodeError list>) : Result<'U, DecodeError list> =
    match r with
    | Error es -> Error es
    | Ok v ->
        match f v with
        | Ok u -> Ok u
        | Error m -> cOne (dFail DecodeCode.OutOfRange "a case its refinement admits" m)

let private colLayoutKind (_: CollectingDecoders) (j: JVal) : Result<LayoutKind, DecodeError list> = cOne (decLayoutKind j)

let private colLevel (_: CollectingDecoders) (j: JVal) : Result<Level, DecodeError list> = cOne (decLevel j)

let private colStrictness (_: CollectingDecoders) (j: JVal) : Result<Strictness, DecodeError list> = cOne (decStrictness j)

let rec private colNodeKind (__ov: CollectingDecoders) (j: JVal) : Result<NodeKind, DecodeError list> =
    cObj j |> Result.bind (fun __fs ->
    dTag __fs |> cOne |> Result.bind (fun __t ->
    match __t with
    | "Bind" -> __ov.BindSpec __ov j |> Result.map NodeKind.Bind
    | "Embed" -> __ov.EmbedSpec __ov j |> Result.map NodeKind.Embed
    | "Group" -> __ov.GroupSpec __ov j |> Result.map NodeKind.Group
