/// Phase 541 — the generated collecting decoders: what every `decode*All` entry reads through, and
/// the record a host copies (`{ collectingDecoders with <Type> = … }`) to override one type.
let collectingDecoders: CollectingDecoders =
    { Node = colNode
      Text = colText
      ContentHash = colContentHash
      Point = colPoint
      BindSpec = colBindSpec
      EmbedSpec = colEmbedSpec
      GroupSpec = colGroupSpec
      LinkSpec = colLinkSpec
      MeasureSpec = colMeasureSpec
      TallySpec = colTallySpec
      LayoutKind = colLayoutKind
      Level = colLevel
      Strictness = colStrictness
      String = colString
      Int = colInt
      Float = colFloat
      Bool = colBool
      Binding =
        { new CollectingBinding with
            member _.Decode(__ov, colT, instT, j) = colBinding __ov colT instT j }
      Slot =
        { new CollectingSlot with
            member _.Decode(__ov, colT, instT, j) = colSlot __ov colT instT j }
      Absent = colAbsent }

/// Phase 377 — the public per-spec decoders. `decode<Tag>Spec` reads one kind's object and
/// answers its FIRST defect; `decode<Tag>SpecAll` reads the same object and answers EVERY defect,
/// in the order stated above the collecting prelude. A consumer delegates one kind at a time.
/// Phase 541 — `decode<Tag>SpecAllWith` reads it through a host's `CollectingDecoders`, so the
/// host's decoder at a type applies at every depth; `decode<Tag>SpecAll` is its no-override case.
let decodeBindSpec (j: JVal) : Result<BindSpec, DecodeError> = decBindSpec j
let decodeBindSpecAll (j: JVal) : Result<BindSpec, DecodeError list> = colBindSpec collectingDecoders j
let decodeBindSpecAllWith (decoders: CollectingDecoders) (j: JVal) : Result<BindSpec, DecodeError list> =
    decoders.BindSpec decoders j
let decodeEmbedSpec (j: JVal) : Result<EmbedSpec, DecodeError> = decEmbedSpec j
let decodeEmbedSpecAll (j: JVal) : Result<EmbedSpec, DecodeError list> = colEmbedSpec collectingDecoders j
let decodeEmbedSpecAllWith (decoders: CollectingDecoders) (j: JVal) : Result<EmbedSpec, DecodeError list> =
