/// The whole node over a parsed value: the first defect, or every defect.
let decodeNodeJson (j: JVal) : Result<Node, DecodeError> = decNode j
let decodeNodeJsonAll (j: JVal) : Result<Node, DecodeError list> = colNode collectingDecoders j
let decodeNodeJsonAllWith (decoders: CollectingDecoders) (j: JVal) : Result<Node, DecodeError list> =
